import random
random.seed(4242)
last_seen = {n: 0 for n in range(1, 60)}
for rnd in range(1, 101):
    for n in random.sample(range(1, 60), 6):
        last_seen[n] = rnd
gaps = sorted(((100 - last_seen[n], n) for n in range(1, 60)), reverse=True)
print("SIMULATED set: 100 rounds")
print("longest absences at end of set (descriptive only):")
for gap, n in gaps[:5]:
    print(f"number {n}: {gap} rounds since last appearance")
print("next-round chance per number: still 6 in 59")
